parameters.jsCode:
// Exnoria - exp.contact.upgrade
// Branch based on signal_id to handle different upgrade scenarios
// Primary: email via Gmail
// Localized: en/es via APP_LOCALE

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, signal_severity } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';

const es = $env.APP_LOCALE === 'es';

let tags = [];
let gmailSubject = '';
let gmailBody = '';
let taskSubject = null;
let taskPriority = 'MEDIUM';

// Branch based on signal_id
if (signal_id === 'EXP_VAL_01') {
  // Unwilling to pay more - send upgrade prompt with tier comparison
  tags.push('exp-upgrade-initiated');
  gmailSubject = es ? 'Desbloquea más valor con nuestro plan premium' : 'Unlock more value with our premium tier';
  gmailBody = es
    ? 'Hola ' + firstname + ', gracias por ser un cliente valioso. Nos encantaría mostrarte cómo puedes obtener aún más de nuestra plataforma. Aquí tienes una comparación de nuestros planes: [ENLACE]'
    : 'Hi ' + firstname + ', thanks for being a valued customer! We\'d love to show you how you can get even more from our platform. Here\'s a comparison of our tiers: [LINK]';
} else if (signal_id === 'EXP_VAL_02') {
  // Low ROI perception - co-create business case
  tags.push('exp-roi-case');
  gmailSubject = es ? 'Construyamos juntos tu caso de negocio de ROI' : 'Let\'s build your ROI business case together';
  gmailBody = es
    ? 'Hola ' + firstname + ', creemos que nuestra plataforma está aportando valor y nos gustaría ayudarte a cuantificarlo. Agendemos una llamada para construir un caso de negocio juntos.'
    : 'Hi ' + firstname + ', we believe our platform is delivering value and we\'d like to help you quantify it. Let\'s schedule a call to build a business case together.';
  taskSubject = (es ? 'Co-crear caso de negocio ROI con ' : 'Co-create ROI business case with ') + contact_id;
  taskPriority = 'HIGH';
}

return [{
  json: {
    contact_id,
    signal_id,
    signal_severity,
    email,
    firstname,
    lastname,
    tags,
    gmail_subject: gmailSubject,
    gmail_body: gmailBody,
    task_subject: taskSubject,
    task_priority: taskPriority
  }
}];

